{
  "items": [
    {
      "label": "FIGURE O.15",
      "kind": "chart",
      "title": "Positive relationship between income levels and GHG emissions",
      "bbox": [
        228,
        167,
        835,
        787
      ],
      "content": {
        "panel_a": {
          "type": "donut chart",
          "title": "Ten economies produce two-thirds of global emissions",
          "data": {
            "66% of global emissions": [
              "CHN",
              "US",
              "IND",
              "IDN",
              "RUS",
              "BRA",
              "JPN",
              "IRN",
              "SAU",
              "DEU"
            ],
            "34% of global emissions": "remaining economies"
          }
        },
        "panel_b": {
          "type": "line chart",
          "title": "Emissions per capita are converging between high- and upper-middle-income countries",
          "y_axis": "GHG emissions per capita (t CO2e)",
          "x_axis": "Year (2000-2022)",
          "legend": [
            "High-income",
            "Upper-middle-income",
            "Lower-middle-income",
            "Low-income"
          ],
          "trends": {
            "High-income": "Starts at approx. 14 t CO2e in 2000, shows a gradual downward trend to approx. 12 t CO2e by 2022.",
            "Upper-middle-income": "Starts at approx. 4 t CO2e in 2000, shows a steady upward trend to approx. 8 t CO2e by 2022.",
            "Lower-middle-income": "Remains relatively flat at approx. 2-3 t CO2e throughout the period.",
            "Low-income": "Remains flat at approx. 1-2 t CO2e throughout the period."
          }
        }
      }
    }
  ]
}
